mapper.select:
SELECT l.id, l.sku_id, l.warehouse_id, l.change_type, l.change_qty,
       l.before_qty, l.after_qty, l.order_id, l.reference_no,
       l.supplier_id, l.supplier_name, l.operator_id, l.remark, l.images,
       l.tenant_id, l.create_time,
       ps.sku_code, w.warehouse_name, u.nickname AS operator_name
FROM inventory_log l
LEFT OUTER JOIN product_sku ps ON l.sku_id = ps.id AND l.tenant_id = ps.tenant_id
LEFT OUTER JOIN warehouse w ON l.warehouse_id = w.id AND l.tenant_id = w.tenant_id
LEFT OUTER JOIN sys_user u ON l.operator_id = u.id AND l.tenant_id = u.tenant_id
WHERE l.tenant_id = #{tenantId}

    AND l.sku_id = #{skuId}


    AND l.warehouse_id = #{warehouseId}


    AND l.change_type = #{changeType}

ORDER BY l.id DESC
LIMIT #{offset}, #{size}

SELECT COUNT(*)
FROM inventory_log l
WHERE l.tenant_id = #{tenantId}

    AND l.sku_id = #{skuId}


    AND l.warehouse_id = #{warehouseId}


    AND l.change_type = #{changeType}
